from copy import deepcopy

_ADDITIVE_CHANNELS = frozenset({'evidence', 'trace'})
_REPLACEMENT_CHANNELS = frozenset({'recommendation', 'valid'})
_ALLOWED_CHANNELS = _ADDITIVE_CHANNELS | _REPLACEMENT_CHANNELS

def apply_state_update(state, update):
    if type(state) is not dict or type(update) is not dict:
        raise TypeError('state_or_update_not_dict')
    if not set(state) <= _ALLOWED_CHANNELS or not set(update) <= _ALLOWED_CHANNELS:
        raise ValueError('unknown_channel')
    result = deepcopy(state)
    for channel in _ADDITIVE_CHANNELS:
        current = result.get(channel, [])
        incoming = update.get(channel, [])
        if type(current) is not list or type(incoming) is not list:
            raise TypeError('additive_channel_not_list')
        if any(type(item) is not str for item in current + incoming):
            raise TypeError('additive_item_not_string')
        if channel in update:
            result[channel] = [*current, *incoming]
    for channel in _REPLACEMENT_CHANNELS:
        if channel in update:
            result[channel] = deepcopy(update[channel])
    return result

