def classify_query(case_orders, case_id, query):
    if type(case_orders) is not dict:
        raise TypeError('case_orders_not_dict')
    if any(type(key) is not str or type(value) is not str for key, value in case_orders.items()):
        raise TypeError('case_orders_invalid')
    if type(case_id) is not str or type(query) is not str:
        raise TypeError('case_or_query_invalid')
    purchase_order_id = case_orders.get(case_id)
    normalized = ' '.join(query.casefold().split())
    supported = bool(
        purchase_order_id
        and ('price' in normalized or 'cost' in normalized)
        and ('purchase order' in normalized or purchase_order_id.casefold() in normalized)
    )
    if not supported:
        return {'intent': 'unsupported'}
    return {
        'intent': 'procurement_price_investigation',
        'purchase_order_id': purchase_order_id,
    }

