from decimal import Decimal, ROUND_HALF_EVEN, localcontext
import re

_PRICE_PATTERN = re.compile(r'(?:0|[1-9]\d*)(?:\.\d+)?\Z')

def price_variance(reference, current, reference_currency, current_currency, reference_unit, current_unit):
    values = (reference, current, reference_currency, current_currency, reference_unit, current_unit)
    if any(type(value) is not str for value in values):
        raise TypeError('input_not_string')
    if not _PRICE_PATTERN.fullmatch(reference) or not _PRICE_PATTERN.fullmatch(current):
        raise ValueError('price_invalid')
    if not reference_currency or not current_currency or not reference_unit or not current_unit:
        raise ValueError('dimension_blank')
    if reference_currency != current_currency or reference_unit != current_unit:
        raise ValueError('dimension_mismatch')
    reference_value = Decimal(reference)
    current_value = Decimal(current)
    if reference_value <= 0:
        raise ValueError('reference_not_positive')
    with localcontext() as context:
        context.prec = 28
        absolute = current_value - reference_value
        percent = absolute / reference_value * Decimal('100')
        quantum = Decimal('0.01')
        return (
            str(absolute.quantize(quantum, rounding=ROUND_HALF_EVEN)),
            str(percent.quantize(quantum, rounding=ROUND_HALF_EVEN)),
        )

