from decimal import Decimal
import re

_DECIMAL_PATTERN = re.compile(r'(?:0|[1-9]\d*)(?:\.\d+)?\Z')

def recommendation(supplier_status, variance_percent, terms_found, max_variance_percent):
    if type(supplier_status) is not str or type(variance_percent) is not str or type(terms_found) is not bool:
        raise TypeError('input_type_invalid')
    if not supplier_status or not _DECIMAL_PATTERN.fullmatch(variance_percent):
        raise ValueError('input_value_invalid')
    if not terms_found:
        if max_variance_percent is not None:
            raise ValueError('missing_terms_must_not_have_threshold')
        return 'needs_human'
    if type(max_variance_percent) is not str:
        raise TypeError('threshold_not_string')
    if not _DECIMAL_PATTERN.fullmatch(max_variance_percent):
        raise ValueError('threshold_invalid')
    if supplier_status != 'active' or Decimal(variance_percent) > Decimal(max_variance_percent):
        return 'review_required'
    return 'no_review'

def validation_errors(state):
    if type(state) is not dict:
        raise TypeError('state_not_dict')
    errors = []
    sql = state.get('sql_analysis')
    contract = state.get('contract')
    recommendation_value = state.get('recommendation')
    variance = state.get('variance_percent')
    evidence = state.get('evidence', [])
    if sql is None:
        errors.append('sql_analysis_required')
    elif type(sql) is not dict:
        raise TypeError('sql_analysis_not_dict')
    if contract is None:
        errors.append('contract_result_required')
    elif type(contract) is not dict:
        raise TypeError('contract_not_dict')
    if recommendation_value not in {'no_review', 'review_required', 'needs_human'}:
        errors.append('recommendation_required')
    if variance is None:
        errors.append('variance_required')
    elif type(variance) is not str:
        raise TypeError('variance_not_string')
    if type(evidence) is not list or any(type(item) is not str for item in evidence):
        raise TypeError('evidence_invalid')
    if not any(item.startswith('sql:') for item in evidence):
        errors.append('sql_evidence_required')
    if not any(item.startswith('document:') for item in evidence):
        errors.append('document_evidence_required')
    return tuple(errors)

