from hashlib import sha256
import json

_REPORT_FIELDS = frozenset({
    'case_id', 'purchase_order_id', 'recommendation', 'reason',
    'variance_percent', 'reference_as_of', 'evidence',
})

def report_digest(report):
    if type(report) is not dict:
        raise TypeError('report_not_dict')
    if set(report) != _REPORT_FIELDS:
        raise ValueError('report_fields_invalid')
    for field in _REPORT_FIELDS - {'evidence'}:
        if type(report[field]) is not str:
            raise TypeError('report_scalar_not_string')
    evidence = report['evidence']
    if type(evidence) is not list or any(type(item) is not str for item in evidence):
        raise TypeError('report_evidence_invalid')
    payload = json.dumps(report, ensure_ascii=True, sort_keys=True, separators=(',', ':'))
    return sha256(payload.encode('utf-8')).hexdigest()

import re

_DIGEST_PATTERN = re.compile(r'[0-9a-f]{64}\Z')

def validate_approval(current_digest, response):
    if type(current_digest) is not str or type(response) is not dict:
        raise TypeError('approval_input_type_invalid')
    if not _DIGEST_PATTERN.fullmatch(current_digest):
        raise ValueError('current_digest_invalid')
    if set(response) != {'decision', 'reviewer', 'report_digest'}:
        raise ValueError('approval_fields_invalid')
    decision = response['decision']
    reviewer = response['reviewer']
    reviewed_digest = response['report_digest']
    if type(decision) is not str or type(reviewer) is not str or type(reviewed_digest) is not str:
        raise TypeError('approval_field_type_invalid')
    if decision not in {'approve', 'reject'}:
        raise ValueError('approval_decision_invalid')
    clean_reviewer = reviewer.strip()
    if not clean_reviewer or len(clean_reviewer) > 80:
        raise ValueError('approval_reviewer_invalid')
    if not _DIGEST_PATTERN.fullmatch(reviewed_digest):
        raise ValueError('approval_digest_invalid')
    if reviewed_digest != current_digest:
        raise ValueError('approval_report_mismatch')
    status = 'approved' if decision == 'approve' else 'rejected'
    return status, clean_reviewer, f'human_approval:{decision}:{clean_reviewer}'

