        raise ValueError('snapshot_status_invalid')
    if type(next_nodes) is not tuple or any(type(item) is not str for item in next_nodes):
        raise TypeError('snapshot_next_invalid')
    if type(checkpoint_count) is not int:
        raise TypeError('checkpoint_count_not_int')
    if checkpoint_count < 1:
        raise ValueError('checkpoint_count_invalid')
    return {
        'thread_id': thread_id,
        'status': status,
        'next': tuple(next_nodes),
        'checkpoint_count': checkpoint_count,
        'interrupted': 'human_approval' in next_nodes,
    }

