import re

_RESUME_DIGEST = re.compile(r'[0-9a-f]{64}\Z')

def prepare_resume(paused_thread, requested_thread, current_digest, response):
    if any(type(value) is not str for value in (paused_thread, requested_thread, current_digest)):
        raise TypeError('resume_scalar_type_invalid')
    if type(response) is not dict:
        raise TypeError('response_not_dict')
    if not paused_thread.strip() or not requested_thread.strip():
        raise ValueError('thread_id_required')
    if len(paused_thread) > 200 or len(requested_thread) > 200:
        raise ValueError('thread_id_too_long')
    if paused_thread != requested_thread:
        raise ValueError('thread_mismatch')
    if not _RESUME_DIGEST.fullmatch(current_digest):
        raise ValueError('current_digest_invalid')
    if set(response) != {'decision','reviewer','report_digest'}:
        raise ValueError('response_fields_invalid')
    decision = response['decision']; reviewer = response['reviewer']; digest = response['report_digest']
    if any(type(value) is not str for value in (decision, reviewer, digest)):
        raise TypeError('response_field_type_invalid')
    if decision not in {'approve','reject'}:
        raise ValueError('decision_invalid')
    clean_reviewer = reviewer.strip()
    if not clean_reviewer or len(clean_reviewer) > 80:
        raise ValueError('reviewer_invalid')
    if not _RESUME_DIGEST.fullmatch(digest) or digest != current_digest:
        raise ValueError('report_mismatch')
    normalized = {'decision':decision,'reviewer':clean_reviewer,'report_digest':digest}
    return (
        {'configurable': {'thread_id': requested_thread}},
        {'resume': normalized},
    )

