def append_trace(trace, event, max_events, max_bytes):
    if type(trace) is not list or any(type(item) is not str for item in trace):
        raise TypeError('trace_invalid')
    if type(event) is not str:
        raise TypeError('event_not_string')
    if not event:
        raise ValueError('event_blank')
    if type(max_events) is not int or type(max_bytes) is not int:
        raise TypeError('budget_not_int')
    if max_events < 1 or max_bytes < 1:
        raise ValueError('budget_not_positive')
    result = [*trace, event]
    if len(result) > max_events:
        raise ValueError('event_budget_exceeded')
    if len('\n'.join(result).encode('utf-8')) > max_bytes:
        raise ValueError('byte_budget_exceeded')
    return result

def checkpoint_metrics(history):
    if type(history) is not list:
        raise TypeError('history_not_list')
    if not history:
        raise ValueError('history_empty')
    thread_id = None
    previous_step = -1
    for row in history:
        if type(row) is not dict:
            raise TypeError('history_row_not_dict')
        if set(row) != {'thread_id','step','status'}:
            raise ValueError('history_fields_invalid')
        if type(row['thread_id']) is not str or type(row['status']) is not str:
            raise TypeError('history_text_invalid')
        if not row['thread_id'] or not row['status']:
            raise ValueError('history_text_blank')
        if type(row['step']) is not int:
            raise TypeError('history_step_not_int')
        if row['step'] < 0:
            raise ValueError('history_step_negative')
        if thread_id is None:
            thread_id = row['thread_id']
        elif row['thread_id'] != thread_id:
            raise ValueError('history_thread_mismatch')
        if row['step'] <= previous_step:
            raise ValueError('history_steps_not_increasing')
        previous_step = row['step']
    return {
        'thread_id': thread_id,
        'checkpoints': len(history),
        'latest_step': history[-1]['step'],
        'latest_status': history[-1]['status'],
    }

