import re

_EFFECT_DIGEST = re.compile(r'[0-9a-f]{64}\Z')
_EFFECT_STATUSES = frozenset({'awaiting_approval','approved','rejected'})

def effect_decision(approval_status, report_digest, recorded_keys):
    if type(approval_status) is not str or type(report_digest) is not str:
        raise TypeError('effect_scalar_type_invalid')
    if type(recorded_keys) is not set or any(type(item) is not str for item in recorded_keys):
        raise TypeError('recorded_keys_invalid')
    if approval_status not in _EFFECT_STATUSES:
        raise ValueError('approval_status_invalid')
    if not _EFFECT_DIGEST.fullmatch(report_digest):
        raise ValueError('report_digest_invalid')
    key = report_digest + ':record'
    result_keys = set(recorded_keys)
    if approval_status != 'approved':
        action = 'blocked'
    elif key in recorded_keys:
        action = 'duplicate'
    else:
        action = 'execute'
        result_keys.add(key)
    return {'action':action,'key':key,'recorded':result_keys}

