_ALLOWED_RUN_STATUSES = frozenset({
    'unsupported','validation_failed','awaiting_approval','approved','rejected',
})

def audit_run(status, trace, evidence):
    if type(status) is not str:
        raise TypeError('status_not_string')
    if status not in _ALLOWED_RUN_STATUSES:
        raise ValueError('status_unknown')
    if type(trace) is not list or type(evidence) is not list:
        raise TypeError('trace_or_evidence_not_list')
    if any(type(item) is not str for item in trace + evidence):
        raise TypeError('trace_or_evidence_item_invalid')
    has_document = any(item.startswith('document:') for item in evidence)
    has_sql = any(item.startswith('sql:') for item in evidence)
    review_boundary = 'validate_report:passed' in trace
    if status == 'unsupported':
        if trace != ['classify_query:unsupported','unsupported_query:end'] or evidence:
            raise ValueError('unsupported_run_inconsistent')
    elif status == 'validation_failed':
        if not trace or trace[-1] != 'validate_report:failed' or review_boundary:
            raise ValueError('validation_failure_inconsistent')
    else:
        if not has_document or not has_sql or not review_boundary:
            raise ValueError('review_run_incomplete')
        if status in {'approved','rejected'}:
            decision = 'approve' if status == 'approved' else 'reject'
            if not trace or not trace[-1].startswith(f'human_approval:{decision}:'):
                raise ValueError('human_transition_inconsistent')
    return {
        'status': status,
